//! Stateful prefix evaluator. Future bars are neither indexed nor read by a decision.
use super::exact::n;
use super::{exact::{D,d,div,div_at,floor_ratio,sqrt,ln_ratio,tanh,text},quant::{Parameters,QuantBar,HistorySemantics,Signal,IndicatorPoint,strategy_catalog},structure::{atr,price_structure_cached,smart_events_cached,TrendState}};
