fn sign(value:&D)->i8{if value>&D::zero(){1}else if value<&D::zero(){-1}else{0}}
fn clamp(value:D,low:&str,high:&str)->D{value.max(d(low)).min(d(high))}
fn average(values:&[D])->Option<D>{if values.is_empty(){None}else{Some(div(&values.iter().cloned().sum::<D>(),&n(values.len())))}}
