        let comparison=if i>=4{sign(&(&close-&self.bars[i-4].close))}else{0};self.nine_streak=if comparison==0{0}else if comparison==self.nine_direction{self.nine_streak.saturating_add(1)}else{1};if comparison!=self.nine_direction{self.nine_perfected=false;}self.nine_direction=comparison;
        if self.nine_streak==9&&i>=3{self.nine_perfected=if comparison>0{self.bars[i].high.clone().max(self.bars[i-1].high.clone())>=self.bars[i-2].high.clone().max(self.bars[i-3].high.clone())}else{self.bars[i].low.clone().min(self.bars[i-1].low.clone())<=self.bars[i-2].low.clone().min(self.bars[i-3].low.clone())};}
        self.recurrences.push(Recurrence{macd,histogram,k:self.k.clone(),kd:self.kd.clone(),j,zone:zone.into(),dulling,cross:cross.into(),streak:self.zone_streak,rsi,rsi_direction,rsi_state:rsi_state.into(),rsi_signal:rsi_signal.into(),nine_direction:self.nine_direction,nine_streak:self.nine_streak,nine_perfected:self.nine_perfected});
        if p.enabled_strategies.contains("auto-trend"){self.trend_state.advance(&self.bars,i,&self.atr14,self.processed_bars-self.bars.len());}
