        values.insert("macd".into(),if processed_bars>=p.macd_slow{json!({"value":text(&macd),"signal":text(&(&macd-&histogram)),"histogram":text(&histogram)})}else{Value::Null});
        add("macd",sign(&histogram),if processed_bars>=p.macd_slow{clamp(d("0.56")+div(&histogram.abs(),&close.clone().max(D::one()))*60,"0.56","0.82")}else{D::zero()},if processed_bars>=p.macd_slow{"ready"}else{"warming"},"MACD 动量",vec![]);
