        values.insert("bollinger".into(),bb.unwrap_or(Value::Null));add("bollinger",bb_direction,if bb_direction==0{D::zero()}else{d("0.61")},if i+1<p.bollinger_period{"warming"}else if values["bollinger"].is_null(){"unavailable"}else{"ready"},"布林波动结构",if values["bollinger"].is_null()&&i+1>=p.bollinger_period{vec!["中轨为零，带宽比例不可定义".into()]}else{vec![]});
